phrases.push(["My name is Ravi.","എന്റെ പേര് രവിയാണ്."],["I am from Kerala.","ഞാൻ കേരളത്തിൽ നിന്നാണ്."],["Nice to meet you.","നിങ്ങളെ കണ്ടതിൽ സന്തോഷം."],["This is my friend.","ഇത് എന്റെ സുഹൃത്താണ്."],["He is my uncle.","അദ്ദേഹം എന്റെ അമ്മാവനാണ്."],["She is my neighbour.","അവൾ എന്റെ അയൽവാസിയാണ്."],["This is the kitchen.","ഇതാണ് അടുക്കള."],["The bedroom is upstairs.","കിടപ്പുമുറി മുകളിലാണ്."],["The bathroom is clean.","കുളിമുറി വൃത്തിയുള്ളതാണ്."],["Where is the key?","താക്കോൽ എവിടെയാണ്?"],["The fan is on.","ഫാൻ പ്രവർത്തിക്കുകയാണ്."],["Please close the door.","ദയവായി വാതിൽ അടയ്ക്കൂ."],["I am sweeping the floor.","ഞാൻ തറ അടിച്ചുവാരുകയാണ്."],["Please clean the table.","ദയവായി മേശ വൃത്തിയാക്കൂ."],["The room is tidy.","മുറി വൃത്തിയിലും ക്രമത്തിലുമാണ്."],["My shirt is blue.","എന്റെ ഷർട്ട് നീലയാണ്."],["Where are my shoes?","എന്റെ ചെരിപ്പുകൾ എവിടെയാണ്?"],["This dress is new.","ഈ വസ്ത്രം പുതിയതാണ്."],["Do you have a smaller size?","ഇതിലും ചെറിയ വലുപ്പമുണ്ടോ?"],["Can I try this on?","ഇത് ധരിച്ചുനോക്കാമോ?"],["I will take this one.","ഞാൻ ഇത് എടുക്കാം."],["How much does it cost?","ഇതിന് എത്ര വിലയാണ്?"],["Can I pay by cash?","പണമായി നൽകാമോ?"],["Please give me the change.","ദയവായി ബാക്കി പണം തരൂ."],["Are these tomatoes fresh?","ഈ തക്കാളികൾ പുതുതാണോ?"],["Give me half a kilo.","എനിക്ക് അര കിലോ തരൂ."],["That is too expensive.","അത് വളരെ വില കൂടുതലാണ്."],["I like bananas.","എനിക്ക് വാഴപ്പഴം ഇഷ്ടമാണ്."],["Cut the onions, please.","ദയവായി ഉള്ളി അരിയൂ."],["These mangoes are ripe.","ഈ മാങ്ങകൾ പഴുത്തതാണ്."],["Boil the water.","വെള്ളം തിളപ്പിക്കൂ."],["Add a little salt.","കുറച്ച് ഉപ്പ് ചേർക്കൂ."],["The rice is ready.","ചോറ് തയ്യാറായി."],["Breakfast is ready.","പ്രഭാതഭക്ഷണം തയ്യാറാണ്."],["Please pass the salt.","ദയവായി ഉപ്പ് തരൂ."],["I have already eaten.","ഞാൻ ഇതിനകം ഭക്ഷണം കഴിച്ചു."],["Where is my classroom?","എന്റെ ക്ലാസ് മുറി എവിടെയാണ്?"],["The class starts at nine.","ക്ലാസ് ഒൻപതിന് തുടങ്ങും."],["I forgot my notebook.","ഞാൻ എന്റെ നോട്ട്ബുക്ക് മറന്നു."],["I have homework today.","എനിക്ക് ഇന്ന് ഹോംവർക്ക് ഉണ്ട്."],["I need to study.","എനിക്ക് പഠിക്കണം."],["Can you explain this?","ഇത് വിശദീകരിക്കാമോ?"],["Please read this word.","ദയവായി ഈ വാക്ക് വായിക്കൂ."],["How do you spell it?","ഇത് എങ്ങനെ അക്ഷരങ്ങളായി എഴുതും?"],["I wrote the answer.","ഞാൻ ഉത്തരം എഴുതി."],["I have three books.","എനിക്ക് മൂന്ന് പുസ്തകങ്ങളുണ്ട്."],["Please count to ten.","ദയവായി പത്ത് വരെ എണ്ണൂ."],["There are five people.","അവിടെ അഞ്ച് പേരുണ്ട്."],["Today is Monday.","ഇന്ന് തിങ്കളാഴ്ചയാണ്."],["My birthday is in May.","എന്റെ ജന്മദിനം മേയിലാണ്."],["What is the date today?","ഇന്ന് തീയതി എത്രയാണ്?"],["It is very small.","ഇത് വളരെ ചെറുതാണ്."],["This bag is heavy.","ഈ ബാഗ് ഭാരമുള്ളതാണ്."],["The water is cold.","വെള്ളം തണുപ്പാണ്."],["How do I get there?","ഞാൻ അവിടെ എങ്ങനെ എത്തും?"],["Turn left at the corner.","മൂലയിൽ ഇടത്തോട്ട് തിരിയൂ."],["Is it far from here?","ഇവിടെ നിന്ന് ദൂരെയാണോ?"],["Where can I buy a ticket?","എനിക്ക് എവിടെ നിന്ന് ടിക്കറ്റ് വാങ്ങാം?"],["Is this seat free?","ഈ സീറ്റ് ഒഴിവാണോ?"],["Please tell me when we arrive.","എത്തുമ്പോൾ ദയവായി എന്നോട് പറയൂ."],["Which platform is it?","ഏത് പ്ലാറ്റ്ഫോമാണ്?"],["The train is delayed.","ട്രെയിൻ വൈകുകയാണ്."],["I need a return ticket.","എനിക്ക് മടക്കയാത്രാ ടിക്കറ്റ് വേണം."],["I am lost.","എനിക്ക് വഴി തെറ്റി."],["Could you show me the way?","വഴി കാണിച്ചുതരാമോ?"],["Thank you for helping me.","എന്നെ സഹായിച്ചതിന് നന്ദി."],["I have a fever.","എനിക്ക് പനിയുണ്ട്."],["My throat hurts.","എന്റെ തൊണ്ട വേദനിക്കുന്നു."],["The pain started yesterday.","വേദന ഇന്നലെ തുടങ്ങി."],["I need this medicine.","എനിക്ക് ഈ മരുന്ന് വേണം."],["How often should I take it?","എത്ര ഇടവേളയിൽ ഇത് കഴിക്കണം?"],["Are there any side effects?","എന്തെങ്കിലും പാർശ്വഫലങ്ങളുണ്ടോ?"],["I drink enough water.","ഞാൻ ആവശ്യത്തിന് വെള്ളം കുടിക്കുന്നു."],["I walk every morning.","ഞാൻ എല്ലാ രാവിലെയും നടക്കുന്നു."],["I need more sleep.","എനിക്ക് കൂടുതൽ ഉറക്കം വേണം."],["I am worried.","എനിക്ക് ആശങ്കയുണ്ട്."],["I feel excited.","എനിക്ക് ആവേശം തോന്നുന്നു."],["I am proud of you.","നിന്നെക്കുറിച്ച് എനിക്ക് അഭിമാനമുണ്ട്."],["Would you like to play?","നിനക്ക് കളിക്കണോ?"],["Can we sit together?","നമുക്ക് ഒരുമിച്ചിരിക്കാമോ?"],["See you tomorrow.","നാളെ കാണാം."],["Welcome to our home.","ഞങ്ങളുടെ വീട്ടിലേക്ക് സ്വാഗതം."],["Please have some food.","ദയവായി കുറച്ച് ഭക്ഷണം കഴിക്കൂ."],["We are happy you came.","നിങ്ങൾ വന്നതിൽ ഞങ്ങൾക്ക് സന്തോഷമുണ്ട്."],["May I speak to Anu?","അനുവിനോട് സംസാരിക്കാമോ?"],["Please hold for a moment.","ദയവായി ഒരു നിമിഷം കാത്തിരിക്കൂ."],["The line is not clear.","ലൈൻ വ്യക്തമല്ല."],["I have sent the message.","ഞാൻ സന്ദേശം അയച്ചു."],["Please check your phone.","ദയവായി ഫോൺ പരിശോധിക്കൂ."],["I will reply soon.","ഞാൻ ഉടൻ മറുപടി നൽകാം."],["Please turn on the computer.","ദയവായി കമ്പ്യൂട്ടർ ഓണാക്കൂ."],["I forgot my password.","ഞാൻ പാസ്‌വേഡ് മറന്നു."],["The internet is not working.","ഇന്റർനെറ്റ് പ്രവർത്തിക്കുന്നില്ല."],["I am ready to start.","ഞാൻ തുടങ്ങാൻ തയ്യാറാണ്."],["What should I do next?","അടുത്തതായി ഞാൻ എന്ത് ചെയ്യണം?"],["I have finished the task.","ഞാൻ ജോലി പൂർത്തിയാക്കി."],["Please tell me about the job.","ദയവായി ജോലിയെക്കുറിച്ച് പറയൂ."],["I am willing to learn.","ഞാൻ പഠിക്കാൻ തയ്യാറാണ്."],["Thank you for the opportunity.","ഈ അവസരത്തിന് നന്ദി."],["I can use a computer.","എനിക്ക് കമ്പ്യൂട്ടർ ഉപയോഗിക്കാം."],["I learn quickly.","ഞാൻ വേഗത്തിൽ പഠിക്കും."],["I work well with others.","എനിക്ക് മറ്റുള്ളവരോടൊപ്പം നന്നായി ജോലി ചെയ്യാം."],["I understand your point.","നിങ്ങളുടെ അഭിപ്രായം എനിക്ക് മനസ്സിലാകുന്നു."],["I see it differently.","ഞാൻ ഇത് വ്യത്യസ്തമായി കാണുന്നു."],["Can we discuss another option?","മറ്റൊരു മാർഗം ചർച്ച ചെയ്യാമോ?"],["May I come in?","ഞാൻ അകത്തേക്ക് വരട്ടേ?"],["Can I borrow your pen?","നിങ്ങളുടെ പേന കടം വാങ്ങാമോ?"],["Is it okay if I leave early?","ഞാൻ നേരത്തെ പോയാൽ പ്രശ്നമുണ്ടോ?"],["Please follow me.","ദയവായി എന്നെ പിന്തുടരൂ."],["Put it on the table.","അത് മേശപ്പുറത്ത് വെക്കൂ."],["Wait until I return.","ഞാൻ മടങ്ങിവരുന്നതുവരെ കാത്തിരിക്കൂ."],["Could you open the window?","ജാലകം തുറക്കാമോ?"],["Please speak a little louder.","ദയവായി കുറച്ചുകൂടി ഉച്ചത്തിൽ സംസാരിക്കൂ."],["Could you help me carry this?","ഇത് കൊണ്ടുപോകാൻ സഹായിക്കാമോ?"],["I am sorry I am late.","വൈകിയതിന് ക്ഷമിക്കണം."],["It was my mistake.","അത് എന്റെ തെറ്റായിരുന്നു."],["I will be careful next time.","അടുത്ത തവണ ഞാൻ ശ്രദ്ധിക്കാം."],["Thank you for your help.","നിങ്ങളുടെ സഹായത്തിന് നന്ദി."],["That is very kind of you.","അത് നിങ്ങളുടെ വലിയ മനസ്സാണ്."],["I really appreciate it.","ഞാൻ അത് വളരെ വിലമതിക്കുന്നു."],["It may rain this evening.","ഇന്ന് വൈകുന്നേരം മഴ പെയ്യാം."],["The sky is cloudy.","ആകാശം മേഘാവൃതമാണ്."],["Carry an umbrella today.","ഇന്ന് ഒരു കുട കരുതൂ."],["I have a reservation.","എനിക്ക് ബുക്കിംഗ് ഉണ്ട്."],["What time is checkout?","ചെക്ക് ഔട്ട് സമയം എത്രയാണ്?"],["Could I have another towel?","മറ്റൊരു ടവൽ തരാമോ?"],["A table for two, please.","രണ്ട് പേർക്കുള്ള മേശ വേണം."],["I do not eat spicy food.","ഞാൻ എരിവുള്ള ഭക്ഷണം കഴിക്കാറില്ല."],["Could we have some water?","കുറച്ച് വെള്ളം തരാമോ?"],["I would like to open an account.","എനിക്ക് ഒരു അക്കൗണ്ട് തുറക്കണം."],["Where should I sign?","ഞാൻ എവിടെ ഒപ്പിടണം?"],["Please check the balance.","ദയവായി ബാലൻസ് പരിശോധിക്കൂ."],["I want to send this parcel.","ഈ പാഴ്സൽ അയയ്ക്കണം."],["How much is the postage?","തപാൽ ചെലവ് എത്രയാണ്?"],["When will it arrive?","ഇത് എപ്പോൾ എത്തും?"],["Please call an ambulance.","ദയവായി ആംബുലൻസ് വിളിക്കൂ."],["I need help immediately.","എനിക്ക് ഉടൻ സഹായം വേണം."],["Please call the police.","ദയവായി പോലീസിനെ വിളിക്കൂ."],["Please be careful.","ദയവായി ശ്രദ്ധിക്കൂ."],["The floor is wet.","തറ നനഞ്ഞിരിക്കുന്നു."],["Do not touch that.","അത് തൊടരുത്."],["Would you like to join us?","ഞങ്ങളോടൊപ്പം ചേരാമോ?"],["What are your plans?","നിങ്ങളുടെ പദ്ധതികൾ എന്താണ്?"],["Let us meet this weekend.","ഈ വാരാന്ത്യത്തിൽ നമുക്ക് കാണാം."],["I went to the market.","ഞാൻ മാർക്കറ്റിൽ പോയി."],["I saw my friend yesterday.","ഞാൻ ഇന്നലെ എന്റെ സുഹൃത്തിനെ കണ്ടു."],["We had a good time.","ഞങ്ങൾക്ക് നല്ല സമയം ചെലവഴിക്കാനായി."],["I will visit you tomorrow.","ഞാൻ നാളെ നിങ്ങളെ സന്ദർശിക്കും."],["I am going to study tonight.","ഞാൻ ഇന്ന് രാത്രി പഠിക്കാൻ പോകുന്നു."],["I hope to see you soon.","നിങ്ങളെ ഉടൻ കാണാമെന്ന് പ്രതീക്ഷിക്കുന്നു."],["I like this idea.","എനിക്ക് ഈ ആശയം ഇഷ്ടമാണ്."],["I think it is useful.","ഇത് ഉപകാരപ്രദമാണെന്ന് ഞാൻ കരുതുന്നു."],["In my opinion, it is better.","എന്റെ അഭിപ്രായത്തിൽ ഇത് കൂടുതൽ നല്ലതാണ്."],["Could you tell me where the bus stop is?","ബസ് സ്റ്റോപ്പ് എവിടെയാണെന്ന് പറയാമോ?"],["I am learning English, so please speak slowly.","ഞാൻ ഇംഗ്ലീഷ് പഠിക്കുകയാണ്, അതിനാൽ ദയവായി പതുക്കെ സംസാരിക്കൂ."],["I did not understand, could you explain it again?","എനിക്ക് മനസ്സിലായില്ല, വീണ്ടും വിശദീകരിക്കാമോ?"]);
phrases.push(["I wake up early.","ഞാൻ നേരത്തെ എഴുന്നേൽക്കുന്നു."],["I make my bed.","ഞാൻ കിടക്ക ഒതുക്കുന്നു."],["I am getting ready.","ഞാൻ തയ്യാറെടുക്കുകയാണ്."],["I come home in the evening.","ഞാൻ വൈകുന്നേരം വീട്ടിലെത്തുന്നു."],["I take some rest.","ഞാൻ കുറച്ച് വിശ്രമിക്കുന്നു."],["I go to sleep early.","ഞാൻ നേരത്തെ ഉറങ്ങാൻ പോകുന്നു."],["Can I play with you?","ഞാൻ നിങ്ങളോടൊപ്പം കളിക്കാമോ?"],["The ball went over there.","പന്ത് അങ്ങോട്ട് പോയി."],["Let's take turns.","നമുക്ക് മാറിമാറി ചെയ്യാം."],["How many people are in your family?","നിങ്ങളുടെ കുടുംബത്തിൽ എത്ര പേരുണ്ട്?"],["We live together.","ഞങ്ങൾ ഒരുമിച്ചാണ് താമസിക്കുന്നത്."],["My family helps me.","എന്റെ കുടുംബം എന്നെ സഹായിക്കുന്നു."],["We have a pet dog.","ഞങ്ങൾക്ക് ഒരു വളർത്തുനായയുണ്ട്."],["The cat is sleeping.","പൂച്ച ഉറങ്ങുകയാണ്."],["Please feed the fish.","ദയവായി മീനുകൾക്ക് തീറ്റ കൊടുക്കൂ."],["Water the plants, please.","ദയവായി ചെടികൾക്ക് വെള്ളമൊഴിക്കൂ."],["This flower is beautiful.","ഈ പൂവ് മനോഹരമാണ്."],["The plant needs sunlight.","ചെടിക്ക് സൂര്യപ്രകാശം വേണം."],["The clothes are wet.","വസ്ത്രങ്ങൾ നനഞ്ഞിരിക്കുന്നു."],["Please hang the clothes.","ദയവായി വസ്ത്രങ്ങൾ ഉണക്കാൻ ഇടൂ."],["I need to iron this shirt.","എനിക്ക് ഈ ഷർട്ട് ഇസ്തിരിയിടണം."],["Be careful, the pan is hot.","ശ്രദ്ധിക്കൂ, പാത്രം ചൂടാണ്."],["Turn off the stove.","അടുപ്പ് ഓഫ് ചെയ്യൂ."],["Keep the knife safely.","കത്തി സുരക്ഷിതമായി വെക്കൂ."],["Please wait for your turn.","ദയവായി നിങ്ങളുടെ ഊഴത്തിനായി കാത്തിരിക്കൂ."],["Hold my hand.","എന്റെ കൈ പിടിക്കൂ."],["Let's go home now.","നമുക്ക് ഇപ്പോൾ വീട്ടിലേക്ക് പോകാം."],["How was school today?","ഇന്ന് സ്കൂൾ എങ്ങനെയുണ്ടായിരുന്നു?"],["My child is not feeling well.","എന്റെ കുട്ടിക്ക് സുഖമില്ല."],["Please tell me about the homework.","ഹോംവർക്കിനെക്കുറിച്ച് ദയവായി പറയൂ."],["I would like to speak to the teacher.","എനിക്ക് ടീച്ചറോട് സംസാരിക്കണം."],["How is my child doing?","എന്റെ കുട്ടിയുടെ പഠനം എങ്ങനെയുണ്ട്?"],["Thank you for your guidance.","നിങ്ങളുടെ മാർഗനിർദേശത്തിന് നന്ദി."],["I am here for an appointment.","ഞാൻ അപ്പോയിന്റ്മെന്റിനായി വന്നതാണ്."],["Where should I wait?","ഞാൻ എവിടെയാണ് കാത്തിരിക്കേണ്ടത്?"],["Here is my name and phone number.","ഇതാണ് എന്റെ പേരും ഫോൺ നമ്പറും."],["I have had a cough for two days.","എനിക്ക് രണ്ട് ദിവസമായി ചുമയുണ്ട്."],["I feel dizzy.","എനിക്ക് തലചുറ്റുന്നു."],["The pain gets worse at night.","രാത്രിയിൽ വേദന കൂടുന്നു."],["Should I take this after food?","ഇത് ഭക്ഷണത്തിന് ശേഷം കഴിക്കണോ?"],["I will follow your advice.","ഞാൻ നിങ്ങളുടെ ഉപദേശം പാലിക്കും."],["When should I come back?","ഞാൻ എപ്പോഴാണ് വീണ്ടും വരേണ്ടത്?"],["Is there a bank nearby?","അടുത്ത് ബാങ്ക് ഉണ്ടോ?"],["How can I reach the market?","എനിക്ക് മാർക്കറ്റിൽ എങ്ങനെ എത്താം?"],["Please show me on the map.","ദയവായി മാപ്പിൽ കാണിച്ചുതരൂ."],["Please take me to this address.","ദയവായി ഈ വിലാസത്തിലേക്ക് കൊണ്ടുപോകൂ."],["How much will the fare be?","യാത്രാക്കൂലി എത്രയായിരിക്കും?"],["Please stop here.","ദയവായി ഇവിടെ നിർത്തൂ."],["Where is the check-in counter?","ചെക്ക്-ഇൻ കൗണ്ടർ എവിടെയാണ്?"],["May I see your passport?","നിങ്ങളുടെ പാസ്‌പോർട്ട് കാണാമോ?"],["When does boarding begin?","ബോർഡിംഗ് എപ്പോഴാണ് തുടങ്ങുന്നത്?"],["I have missed my bus.","എന്റെ ബസ് നഷ്ടപ്പെട്ടു."],["My bag is missing.","എന്റെ ബാഗ് കാണാനില്ല."],["Who can I ask for help?","ആരോടാണ് സഹായം ചോദിക്കേണ്ടത്?"],["I would like to book a time.","എനിക്ക് ഒരു സമയം ബുക്ക് ചെയ്യണം."],["Is tomorrow morning available?","നാളെ രാവിലെ സമയം ലഭ്യമാണോ?"],["Please confirm the appointment.","ദയവായി അപ്പോയിന്റ്മെന്റ് സ്ഥിരീകരിക്കൂ."],["Is there a discount?","വിലക്കുറവുണ്ടോ?"],["That is outside my budget.","അത് എന്റെ ബജറ്റിന് പുറത്താണ്."],["Can you make it a little cheaper?","കുറച്ചുകൂടി വില കുറയ്ക്കാമോ?"],["Where should I submit this form?","ഈ ഫോം എവിടെയാണ് സമർപ്പിക്കേണ്ടത്?"],["What documents do I need?","എനിക്ക് ഏതെല്ലാം രേഖകൾ വേണം?"],["How long will the process take?","ഈ നടപടിക്ക് എത്ര സമയം എടുക്കും?"],["Please help me fill this in.","ഇത് പൂരിപ്പിക്കാൻ എന്നെ സഹായിക്കൂ."],["What should I write here?","ഇവിടെ ഞാൻ എന്താണ് എഴുതേണ്ടത്?"],["I have checked all the details.","ഞാൻ എല്ലാ വിവരങ്ങളും പരിശോധിച്ചു."],["Can I borrow this book?","ഈ പുസ്തകം കടം വാങ്ങാമോ?"],["When should I return it?","ഇത് എപ്പോഴാണ് തിരികെ നൽകേണ്ടത്?"],["Where are the English books?","ഇംഗ്ലീഷ് പുസ്തകങ്ങൾ എവിടെയാണ്?"],["Let's practise five words.","നമുക്ക് അഞ്ച് വാക്കുകൾ പരിശീലിക്കാം."],["Please say it slowly.","ദയവായി പതുക്കെ പറയൂ."],["Mistakes help us learn.","തെറ്റുകൾ നമ്മെ പഠിക്കാൻ സഹായിക്കുന്നു."],["I can read simple words.","എനിക്ക് ലളിതമായ വാക്കുകൾ വായിക്കാം."],["I am still learning.","ഞാൻ ഇപ്പോഴും പഠിച്ചുകൊണ്ടിരിക്കുകയാണ്."],["I need a little more practice.","എനിക്ക് കുറച്ചുകൂടി പരിശീലനം വേണം."],["This one is bigger.","ഇത് വലുതാണ്."],["That one is less expensive.","അതിന് വില കുറവാണ്."],["Both options are good.","രണ്ട് വഴികളും നല്ലതാണ്."],["There is a problem with my order.","എന്റെ ഓർഡറിൽ ഒരു പ്രശ്നമുണ്ട്."],["I received the wrong item.","എനിക്ക് തെറ്റായ സാധനമാണ് ലഭിച്ചത്."],["Could you please help me fix it?","ഇത് പരിഹരിക്കാൻ സഹായിക്കാമോ?"],["I would like to report a problem.","ഒരു പ്രശ്നം അറിയിക്കണം."],["The service was delayed.","സേവനം വൈകി."],["Could you check this, please?","ദയവായി ഇത് പരിശോധിക്കാമോ?"],["Would you like to visit us?","ഞങ്ങളെ സന്ദർശിക്കാൻ വരാമോ?"],["Please come around six.","ദയവായി ആറുമണിയോടെ വരൂ."],["I hope you can come.","നിങ്ങൾക്ക് വരാൻ കഴിയുമെന്ന് പ്രതീക്ഷിക്കുന്നു."],["It was nice talking to you.","നിങ്ങളോട് സംസാരിച്ചതിൽ സന്തോഷം."],["I have to go now.","എനിക്ക് ഇപ്പോൾ പോകണം."],["Talk to you soon.","ഉടൻ വീണ്ടും സംസാരിക്കാം."],["Yesterday, I went to the park.","ഇന്നലെ ഞാൻ പാർക്കിൽ പോയി."],["I met an old friend there.","അവിടെ ഞാൻ ഒരു പഴയ സുഹൃത്തിനെ കണ്ടു."],["We talked and came home.","ഞങ്ങൾ സംസാരിച്ചു, പിന്നെ വീട്ടിലേക്ക് വന്നു."]);

